[
  {
    "text": "Experience Distillation retains at least 64.8% of the gains from in-context learning across software-engineering tasks and text-adventure games.",
    "topic": "Experience Distillation effectiveness"
  },
  {
    "text": "Direct supervised fine-tuning on collected experience recovers only 3.8% of the gains from in-context learning.",
    "topic": "Supervised fine-tuning comparison"
  },
  {
    "text": "In-context learning followed by Experience Distillation matches classical reinforcement-learning baselines with at least 9.6× fewer environment samples.",
    "topic": "Sample efficiency vs. reinforcement learning"
  },
  {
    "text": "Experience Distillation requires no further environment interaction beyond the collected experience.",
    "topic": "No additional environment interactions"
  },
  {
    "text": "The study was conducted on 749 curated software-engineering tasks and six text-adventure games.",
    "topic": "Experimental domains"
  }
]
